UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b358820-jo6vjvBKj5tB.png', birthday = NULL, blood_type = NULL, voice_actor = '武蔵真之介', height = NULL, description = NULL WHERE character_id = 'CH004237';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b321572-eO5gwpL72Zqv.png', birthday = NULL, blood_type = NULL, voice_actor = '小倉唯', height = NULL, description = 'ジルは、優れたコミュニケーション能力と明るい人柄を持つフリーランスのジャーナリストです。' WHERE character_id = 'CH004238';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323382-hFK8LmarXFg8.png', birthday = NULL, blood_type = NULL, voice_actor = '白石晴香', height = NULL, description = 'サイアンは、ロジェの妹だと名乗るヨン・ニアンだ。' WHERE character_id = 'CH004239';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324142-fTUeWTafqklr.png', birthday = NULL, blood_type = NULL, voice_actor = '斉藤貴美子', height = NULL, description = NULL WHERE character_id = 'CH004240';
