UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323955-zppsA1Z8YEUb.png', birthday = NULL, blood_type = NULL, voice_actor = '大西沙織', height = NULL, description = NULL WHERE character_id = 'CH004287';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b330681-8L91SAnVcnK3.png', birthday = NULL, blood_type = NULL, voice_actor = '高森奈津美', height = NULL, description = NULL WHERE character_id = 'CH004288';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213901-ummxYlC1m6sI.png', birthday = NULL, blood_type = NULL, voice_actor = '加隈亜衣', height = NULL, description = 'レンジャー組織に所属するレンジャーの一人。レンジャーとして悪の組織を倒すという役割を担っているものの、彼女は魔法少女になることを夢見ている。' WHERE character_id = 'CH004289';
