UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b326075-4yiVRXpKit1r.png', birthday = NULL, blood_type = NULL, voice_actor = '坂本真綾', height = NULL, description = NULL WHERE character_id = 'CH004291';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b330674-NrzvKR13JNf1.png', birthday = NULL, blood_type = NULL, voice_actor = '白石涼子', height = NULL, description = NULL WHERE character_id = 'CH004292';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213899-2H8vgTySdWub.png', birthday = NULL, blood_type = NULL, voice_actor = '江口拓也', height = NULL, description = '父親がレンジャーになった後、ブルーはブラックによって新たなレンジャーに選ばれることになった。' WHERE character_id = 'CH004293';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b330675-HVeHteR7sNFi.png', birthday = NULL, blood_type = NULL, voice_actor = '本渡楓', height = NULL, description = NULL WHERE character_id = 'CH004294';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b213900-uVknNISiJDQt.png', birthday = NULL, blood_type = NULL, voice_actor = '梅原裕一郎', height = NULL, description = '現在のレンジャーグループの中で最年長であり、メンバーを集めた人物である。眠そうな様子を見せることが多く、難解な言葉遣いをする。いつも忙しそうにしており、守護者としての役割を担っている。' WHERE character_id = 'CH004295';
